Parameter.Description:
Class name of application this page belongs to.
Parameter APPLICATION = "JayZenPkg.PopUpWindow";
Displayed name of this page.

Method.Implementation:
try {
  // if there is already a form, get rid of it
  var comp = zen(formId);
  if (comp) {
    zenPage.deleteComponent(comp);
  }

  var group = zen(groupId);
  var form = zenPage.createComponentNS('JayZenPkg',formClass);
  form.setProperty('id',formId);
  group.addChild(form);
  group.refreshContents(true);
}
catch(ex) {
  zenExceptionHandler(ex,arguments);
}
